// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.selfmodifyimport com.roshan.persona.brain.skill.sandbox.JsSandboximport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport org.mozilla.javascript.ClassShutterimport org.mozilla.javascript.Contextimport org.mozilla.javascript.ContextFactoryimport org.mozilla.javascript.RhinoExceptionimport org.mozilla.javascript.Scriptableimport org.mozilla.javascript.ScriptableObjectimport org.mozilla.javascript.Undefinedimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Real Rhino JavaScript sandbox (Module 15 — Self-modify). * * Implements Brain's [JsSandbox] interface using the Mozilla Rhino 1.7.15 * JavaScript engine. This is the REAL implementation that replaces Brain's * `FakeJsSandbox` (returns canned results) and `NoOpJsSandbox` (always fails) * per Strategy §14.2 Table 3. * * ## Flavor gating * * This class lives in `src/selfmodify/kotlin/` — a custom source dir added * to BOTH the `dev` and `internal` flavors (see `build.gradle.kts`). In the * `prod` flavor, this file is NOT compiled, so `RhinoJsSandbox` is absent * from the classpath and Hilt's DI graph falls back to Brain's * `NoOpJsSandbox`. This satisfies ADR 0008's "Play Store safe" requirement. * * ## Security model (defense in depth) * * Five independent layers prevent a malicious script from escaping: * * 1. **`initSafeStandardObjects()`** — Rhino's restricted global object set. *    No LiveConnect (Java interop), no `Packages`, no `importPackage`, no *    `JavaAdapter`. Scripts see only ECMAScript built-ins (Object, Array, *    Math, JSON, etc.). * * 2. **[SecurityClassShutter]** — defense-in-depth class filter. Even if a *    script somehow reaches a Java class, the shutter blocks `java.io.*`, *    `java.net.*`, `java.lang.reflect.*`, `java.lang.Runtime`, *    `java.lang.ProcessBuilder`, `android.*`, `dalvik.*`, `sun.*`, etc. * * 3. **Interpreted mode (`setOptimizationLevel(-1)`)** — no JIT compilation. *    Rhino's bytecode generator is disabled, so scripts cannot generate JVM *    bytecode at runtime. Eliminates an entire class of escape vectors *    (crafted bytecode that tricks the JVM verifier). * * 4. **Instruction observer + wall-clock timeout** — a custom *    [SandboxContextFactory] overrides `observeInstructionCount` to abort *    scripts that exceed [SandboxLimits.maxExecutionMs] or *    [SandboxLimits.maxInstructions]. Prevents `while(true)` loops and *    quadratic algorithms. * * 5. **JVM heap monitor** — the same observer samples *    `Runtime.totalMemory() - Runtime.freeMemory()` and aborts scripts that *    exceed [SandboxLimits.maxMemoryMb]. Prevents memory-exhaustion DoS. * * ## API surface exposed to JS * * Scripts see: *  - All ECMAScript 6 built-ins (Object, Array, Math, JSON, Date, RegExp, *    Map, Set, Promise, Symbol, etc.) *  - `params` — a plain JS object containing the execution parameters *    (converted from the Kotlin `Map<String, Any>` passed to [execute]). * * Scripts do NOT see: *  - Any Java class (no `java.*`, `javax.*`, `android.*`, `org.*` access) *  - Any Android framework API *  - The file system, network, or process spawning *  - Rhino internals (`org.mozilla.javascript.*`) * * ## Execution flow * * 1. Caller invokes `execute(script, params, limits)` (suspend). * 2. We switch to `Dispatchers.Default` (CPU-bound, bounded pool). * 3. Enter a Rhino Context via our [SandboxContextFactory]. * 4. Configure per-execution limits (instruction observer threshold). * 5. Stash per-execution state (start time, memory budget) in a `ThreadLocal` *    so the factory's `observeInstructionCount` callback can read it. * 6. Init safe standard objects, inject `params`. * 7. `Context.evaluateString(scope, script, "skill", 1, null)`. * 8. Convert the JS result to String via `Context.toString()`. * 9. Map any exception to a [SandboxResult] variant. * 10. Exit the context, clear the ThreadLocal, return. * * ## Thread safety * * `RhinoJsSandbox` is a [Singleton] — one instance, shared across all * callers. The Rhino [Context] is thread-local (one per thread), so * concurrent calls on different threads are isolated. The [SandboxContextFactory] * is stateless beyond the per-thread Context it manages, so it's safe to * share across threads. * * @see JsSandbox * @see SandboxLimits * @see SandboxResult * @see SelfModifyEngine * @see <a href="docs/adr/0008-self-modifying-js-flavor-gated.md">ADR 0008</a> */@Singletonclass RhinoJsSandbox @Inject constructor() : JsSandbox {    /**     * Per-factory (effectively per-singleton) custom ContextFactory.     *     * Overriding [observeInstructionCount] gives us a callback that fires     * every [SandboxLimits.instructionCheckInterval] bytecode instructions     * — the single chokepoint where we enforce wall-clock timeout, memory     * limit, and total instruction count.     *     * We deliberately do NOT install this as the global ContextFactory —     * doing so would conflict with other libraries that might use Rhino.     * Instead we enter/exit contexts via [enterContext] / [exitContext],     * which uses this factory directly.     */    private val contextFactory: ContextFactory = SandboxContextFactory()    override suspend fun execute(        script: String,        params: Map<String, Any>,        limits: com.roshan.persona.brain.skill.sandbox.SandboxLimits,    ): Result<String> {        val correlationId = CorrelationId.generate()        val startNanos = System.nanoTime()        if (!isAvailable()) {            return Result.Failure(                error = AppError.Skill.Crashed(                    skillName = "js_sandbox",                    cause = IllegalStateException("Rhino sandbox not available in this build"),                ),                correlationId = correlationId,                durationNanos = 0,            )        }        // Convert Brain's portable SandboxLimits → Rhino-specific SandboxLimits.        // Brain's limits use byte-level memory + a generic timeout; Rhino's        // adds an explicit instruction-count budget (the most precise way to        // cap CPU usage in interpreted mode).        val rhinoLimits = SandboxLimits(            maxExecutionMs = limits.timeoutMs,            maxMemoryMb = (limits.maxMemoryBytes / BYTES_PER_MB).toInt().coerceAtLeast(1),            maxInstructions = SandboxLimits.DEFAULT_MAX_INSTRUCTIONS,            instructionCheckInterval = SandboxLimits.DEFAULT_INSTRUCTION_CHECK_INTERVAL,        )        // Run on Dispatchers.Default — Rhino is CPU-bound (no I/O allowed in        // the sandbox). The block is non-suspending internally, so it stays        // on a single thread for the entire duration (preserving the        // ThreadLocal invariant).        val sandboxResult: SandboxResult = withContext(Dispatchers.Default) {            executeInternal(script = script, params = params, limits = rhinoLimits)        }        val durationNanos = System.nanoTime() - startNanos        return sandboxResult.toResult(            correlationId = correlationId,            durationNanos = durationNanos,        )    }    /** Rhino is always available in dev/internal flavors (where this class is compiled). */    override fun isAvailable(): Boolean = true    // ─── Internal execution (non-suspending, single-threaded) ──────────────    @Suppress("UNUSED_PARAMETER", "DEPRECATION") // script/params/limits used inside the try block;    // DEPRECATION: Rhino 1.7.15 deprecates `ContextFactory.enter()` and    // `ContextFactory.exit()` instance methods in favor of `factory.call(action)`.    // We keep the explicit enter/exit pattern because our try/catch/finally    // structure (with per-execution ThreadLocal state setup BEFORE entering    // the context) doesn't fit the `call(action)` shape cleanly. The    // deprecated methods still work correctly in 1.7.15.    private fun executeInternal(        script: String,        params: Map<String, Any>,        limits: SandboxLimits,    ): SandboxResult {        // CRITICAL FIX #45: Validate script size before execution (prevent memory exhaustion)        val maxScriptSizeBytes = 100 * 1024  // 100KB max script size        if (script.length > maxScriptSizeBytes) {            Timber.tag(TAG).w("Script too large: ${script.length} bytes (max: $maxScriptSizeBytes)")            return SandboxResult.ScriptError(message = "Script exceeds maximum size (${maxScriptSizeBytes} bytes)", line = -1)        }                // CRITICAL FIX #46: Check for suspicious patterns in script        val suspiciousPatterns = listOf(            "java.lang.Runtime",            "java.lang.ProcessBuilder",            "getClass().forName",            "ClassLoader",            "importPackage",            "JavaAdapter",            "__proto__",            "eval(",            "Function("        )                for (pattern in suspiciousPatterns) {            if (script.contains(pattern)) {                Timber.tag(TAG).w("Suspicious pattern detected in script: $pattern")                return SandboxResult.SecurityViolation(reason = "Suspicious pattern: $pattern")            }        }                val startNanos = System.nanoTime()        // Stash per-execution state for the ContextFactory's observer.        // ThreadLocal so concurrent executions on different threads don't        // stomp on each other.        val execState = ExecutionContext(            startTimeNanos = startNanos,            maxExecutionMs = limits.maxExecutionMs,            maxMemoryBytes = limits.maxMemoryMb.toLong() * BYTES_PER_MB,            maxInstructions = limits.maxInstructions,        )        EXEC_STATE.set(execState)        var context: Context? = null        try {            context = contextFactory.enterContext()            // ─── Layer 3: interpreted mode (no JIT) ───────────────────────            // -1 = interpreted; 0 = no JIT (deprecated alias); >0 = JIT bytecode gen.            // Interpreted mode is slower but eliminates a class of escape vectors            // where malicious scripts craft JVM bytecode to bypass verification.            context.optimizationLevel = -1            context.languageVersion = Context.VERSION_ES6            // ─── Layer 2: ClassShutter (defense in depth) ─────────────────            // Must be set BEFORE initSafeStandardObjects() so it applies to any            // class touched during init.            //            // Use the explicit setter — Kotlin doesn't expose `classShutter`            // as a property because Rhino's `getClassShutter()` is            // package-private (only `setClassShutter` is public).            context.setClassShutter(SecurityClassShutter)            // ─── Layer 4: instruction observer threshold ──────────────────            // Triggers our SandboxContextFactory.observeInstructionCount every            // N bytecode instructions.            context.instructionObserverThreshold = limits.instructionCheckInterval            // ─── Layer 1: safe standard objects (no LiveConnect) ──────────            val scope = context.initSafeStandardObjects()            // Inject `params` as a plain JS object (NOT a NativeJavaObject            // wrapper) so scripts can use `params.foo` directly.            injectParams(context, scope, params)            // ─── Execute ─────────────────────────────────────────────────            val result = context.evaluateString(scope, script, "skill", 1, null)            val durationMs = (System.nanoTime() - startNanos) / NANOS_PER_MILLI            val output = stringifyResult(result)            return SandboxResult.Success(output = output, durationMs = durationMs)        } catch (abort: SandboxAbortException) {            val durationMs = (System.nanoTime() - startNanos) / NANOS_PER_MILLI            return when (abort.reason) {                AbortReason.TIMEOUT -> SandboxResult.Timeout(durationMs = durationMs)                AbortReason.MEMORY ->                    SandboxResult.MemoryLimit(usedMb = abort.usedMb ?: 0)                AbortReason.INSTRUCTIONS -> SandboxResult.Timeout(durationMs = durationMs)            }        } catch (e: RhinoException) {            // Rhino wraps JS-level errors in EcmaError; native-code errors            // in WrappedException. Both extend RhinoException.            val message = e.message ?: e.javaClass.simpleName            val line = runCatching { e.lineNumber() }.getOrDefault(-1)            // Detect security-violation-flavored messages (ClassShutter blocks            // result in "TypeError: Cannot find function X in object [JavaPackage ...]"            // or similar). We treat them as security violations rather than            // script errors so [SelfModifyEngine] can quarantine them.            val isSecurityViolation = message.contains("JavaPackage", ignoreCase = true) ||                message.contains("access to Java class", ignoreCase = true) ||                message.contains("blocked by ClassShutter", ignoreCase = true) ||                message.contains("not allowed in sandboxed context", ignoreCase = true)            if (isSecurityViolation) {                Timber.w("Rhino security violation: %s (line %d)", message, line)                return SandboxResult.SecurityViolation(reason = "$message (line $line)")            } else {                Timber.d("Rhino script error: %s (line %d)", message, line)                return SandboxResult.ScriptError(message = message, line = line)            }        } catch (e: StackOverflowError) {            // Rhino maps infinite recursion to StackOverflowError before the            // instruction observer fires — handle it explicitly.            val message = "Stack overflow (infinite recursion?)"            Timber.w("Rhino stack overflow: %s", e.message)            return SandboxResult.ScriptError(message = message, line = -1)        } catch (e: OutOfMemoryError) {            // JVM-level OOM (rare — the heap observer usually catches it first).            val usedMb = ((Runtime.getRuntime().totalMemory() -                Runtime.getRuntime().freeMemory()) / BYTES_PER_MB).toInt()            Timber.w("Rhino OOM: usedMb=%d", usedMb)            return SandboxResult.MemoryLimit(usedMb = usedMb)        } catch (e: Throwable) {            // Catch-all for any other JVM-level exception.            val message = e.message ?: e.javaClass.simpleName            Timber.w(e, "Rhino unexpected error")            return SandboxResult.ScriptError(message = message, line = -1)        } finally {            EXEC_STATE.remove()            if (context != null) {                // `ContextFactory.exit()` is the public final instance method                // that pairs with `enter()`/`enterContext()` — it looks up                // the current thread's Context and releases it via this                // factory. (`exitContext(Context)` is protected — not callable.)                runCatching { contextFactory.exit() }            }        }    }    // ─── Helpers ───────────────────────────────────────────────────────────    /**     * Inject `params` as a plain JS object (NativeObject) on [scope].     *     * We don't pass the raw Kotlin Map to Rhino (which would wrap it as a     * NativeJavaObject) because:     *  1. Scripts would see Java method names (`get`, `put`, `keySet`, etc.)     *     instead of treating it as a plain JS object.     *  2. LiveConnect access to the Map's class would expose     *     `java.util.LinkedHashMap` — a ClassShutter trip hazard.     *     * Instead we build a NativeObject and copy each entry, recursively     * converting Java values to JS via [Context.javaToJS].     */    private fun injectParams(        context: Context,        scope: Scriptable,        params: Map<String, Any>,    ) {        val paramsObj = context.newObject(scope)        for ((key, value) in params) {            val jsValue = Context.javaToJS(value, scope)            paramsObj.put(key, paramsObj, jsValue)        }        ScriptableObject.putProperty(scope, "params", paramsObj)    }    /**     * Convert a Rhino result value to a String for return to the caller.     *     * - `undefined` → "undefined"     * - `null` → "null"     * - numbers/booleans/strings → their JS `toString()` form     * - objects → `toString()` (or `"[object Object]"` if not overridden)     */    private fun stringifyResult(result: Any?): String = when (result) {        null -> "null"        is Undefined -> "undefined"        else -> {            // Context.toString handles all Scriptable + primitive types.            // For objects without a custom toString, returns "[object Object]".            runCatching { Context.toString(result) }.getOrElse { result.toString() }        }    }    // ─── Per-execution state (thread-local) ────────────────────────────────    /**     * Per-thread per-execution state, read by [SandboxContextFactory.observeInstructionCount].     *     * Set in [executeInternal] before `Context.enter`, cleared in `finally`.     * The ThreadLocal ensures concurrent executions on different threads     * don't stomp on each other.     */    internal companion object {        /** CRITICAL FIX #48: Tag for logging */        private const val TAG = "RhinoJsSandbox"        /** Bytes per megabyte (for memory-limit conversions). */        const val BYTES_PER_MB: Long = 1024L * 1024L        /** Nanoseconds per millisecond (for duration conversions). */        const val NANOS_PER_MILLI: Long = 1_000_000L                /** Maximum script size in bytes (CRITICAL FIX #45) */        const val MAX_SCRIPT_SIZE_BYTES = 100 * 1024        /**         * Per-thread per-execution state.         *         * `internal` so [SandboxContextFactory] (same package) can read it.         * Set in [executeInternal], cleared in `finally`. Null when no         * sandboxed execution is in progress on this thread.         */        val EXEC_STATE: ThreadLocal<ExecutionContext?> = ThreadLocal()    }}/** * Per-execution state stashed in a ThreadLocal for the ContextFactory's * instruction-count observer to read. * * Created per [RhinoJsSandbox.executeInternal] call. */internal data class ExecutionContext(    val startTimeNanos: Long,    val maxExecutionMs: Long,    val maxMemoryBytes: Long,    val maxInstructions: Long,)/** * Reason the sandbox was forcibly aborted. * * Thrown as [SandboxAbortException] from * [SandboxContextFactory.observeInstructionCount] — Rhino unwinds the script * via the exception, [RhinoJsSandbox.executeInternal] catches it and maps * to the corresponding [SandboxResult] variant. */internal enum class AbortReason { TIMEOUT, MEMORY, INSTRUCTIONS }/** * Internal abort exception thrown by [SandboxContextFactory.observeInstructionCount]. * * Extends [Error] (not [Exception]) because Rhino's instruction observer is * called from deep within the interpreter loop — using Error ensures it * propagates past any try/catch the script itself has set up. */internal class SandboxAbortException(    val reason: AbortReason,    val usedMb: Int? = null,) : Error("Sandbox aborted: $reason")// ─── SandboxContextFactory ────────────────────────────────────────────────/** * Custom Rhino [ContextFactory] that enforces wall-clock timeout, memory * limit, and instruction count limit via [observeInstructionCount]. * * Created once per [RhinoJsSandbox] (which is a Singleton). Used via * [enterContext] / [exitContext] (NOT installed globally) to avoid conflicts * with other libraries that might use Rhino. * * The factory itself is stateless beyond the per-thread Context it manages. * Per-execution state (start time, memory budget) is read from * [RhinoJsSandbox.EXEC_STATE] (a ThreadLocal) so concurrent executions on * different threads don't stomp on each other. */private class SandboxContextFactory : ContextFactory() {    /**     * Called by Rhino every `instructionObserverThreshold` bytecode ops.     *     * Single chokepoint for all three resource limits:     *  1. Wall-clock timeout (check `System.nanoTime()` against start).     *  2. JVM heap usage (sample `Runtime.totalMemory() - Runtime.freeMemory()`).     *  3. Total instruction count (check `instructionCount` against budget).     *     * If any limit is exceeded, throw [SandboxAbortException] — Rhino unwinds     * the script via the exception. [RhinoJsSandbox.executeInternal] catches     * it and maps to the appropriate [SandboxResult] variant.     *     * If no execution is in progress on this thread ([EXEC_STATE] is null),     * the callback is a no-op (defensive — shouldn't happen in practice).     */    override fun observeInstructionCount(cx: Context, instructionCount: Int) {        val state = RhinoJsSandbox.EXEC_STATE.get() ?: return        // ─── 1. Wall-clock timeout ────────────────────────────────────────        val elapsedMs = (System.nanoTime() - state.startTimeNanos) /            RhinoJsSandbox.NANOS_PER_MILLI        if (elapsedMs > state.maxExecutionMs) {            throw SandboxAbortException(AbortReason.TIMEOUT)        }        // ─── 2. JVM heap usage ────────────────────────────────────────────        // Coarse: applies to the entire JVM, not just this context.        // (Rhino doesn't expose per-context allocation accounting.)        val runtime = Runtime.getRuntime()        val usedBytes = runtime.totalMemory() - runtime.freeMemory()        if (usedBytes > state.maxMemoryBytes) {            val usedMb = (usedBytes / RhinoJsSandbox.BYTES_PER_MB).toInt()            throw SandboxAbortException(AbortReason.MEMORY, usedMb = usedMb)        }        // ─── 3. Total instruction count ──────────────────────────────────        // instructionCount is Int (Rhino API) — clamp to Long for comparison.        if (instructionCount.toLong() > state.maxInstructions) {            throw SandboxAbortException(AbortReason.INSTRUCTIONS)        }    }}// ─── SecurityClassShutter ─────────────────────────────────────────────────/** * Rhino [ClassShutter] that blocks access to dangerous Java classes. * * Defense-in-depth layer on top of [Context.initSafeStandardObjects] (which * already disables LiveConnect). If a script somehow reaches a Java class * (e.g., via a future Rhino bug or a JSON-deserialization gadget), this * shutter blocks: * *  - `java.io.*` — file system access *  - `java.net.*` — network access *  - `java.lang.reflect.*` — reflection (can bypass other restrictions) *  - `java.lang.Runtime`, `java.lang.ProcessBuilder`, `java.lang.Process` — *    process execution *  - `java.lang.ClassLoader`, `java.lang.Thread` — class loading / threads *  - `java.lang.System` — env vars, exit, etc. *  - `javax.*` — crypto, JNDI, scripting, etc. *  - `android.*` — entire Android framework *  - `dalvik.*` — Dalvik VM internals *  - `sun.*`, `com.sun.*` — JVM internals (often have privileged methods) *  - `org.mozilla.javascript.*` — Rhino internals (can be used to escape) * * Allowed: ECMAScript built-ins (which are Rhino-native, not Java classes), * `java.lang.String`, `java.lang.Number`, `java.lang.Boolean`, * `java.util.*` collections (read-only access for params). * * Note: with `initSafeStandardObjects()`, this shutter is mostly redundant — * LiveConnect is already disabled. But it's a cheap, robust defense against * future Rhino bugs or deserialization gadgets. * * Stateless singleton — same filter for all executions. */private object SecurityClassShutter : ClassShutter {    /**     * Class-name prefixes that are ALWAYS blocked.     *     * A script that tries to access any class whose fully-qualified name     * starts with one of these prefixes gets a `TypeError` from Rhino.     */    private val BLOCKED_PREFIXES: List<String> = listOf(        // File system        "java.io.",        // Network        "java.net.",        "java.nio.channels.",        "java.nio.file.",        // Reflection        "java.lang.reflect.",        // Process execution        "java.lang.Runtime",        "java.lang.ProcessBuilder",        "java.lang.Process",        // Class loading / threads        "java.lang.ClassLoader",        "java.lang.Thread",        "java.lang.InheritableThreadLocal",        // System access (env, exit, etc.)        "java.lang.System",        "java.lang.ThreadGroup",        // Java extensions        "javax.",        // Android framework        "android.",        "androidx.",        // Dalvik VM internals        "dalvik.",        // JVM internals        "sun.",        "com.sun.",        "jdk.",        // Rhino internals (escape vector)        "org.mozilla.javascript.",        // NOUS internals (escape vector into our own code)        "com.roshan.persona.",    )    /**     * Class-name prefixes that are ALWAYS allowed (overrides blocked prefixes     * for specific safe classes).     *     * e.g., `java.lang.String` is allowed even though we don't block     * `java.lang.` by default — but if we ever did, this whitelist would     * still permit the safe primitive wrappers.     */    private val ALLOWED_PREFIXES: List<String> = listOf(        // Primitive wrappers (immutable, safe)        "java.lang.String",        "java.lang.Boolean",        "java.lang.Integer",        "java.lang.Long",        "java.lang.Double",        "java.lang.Float",        "java.lang.Short",        "java.lang.Byte",        "java.lang.Character",        "java.lang.Number",        "java.lang.Math",        // Collections (read-only is safe; mutations only affect the JS view)        "java.util.ArrayList",        "java.util.HashMap",        "java.util.LinkedHashMap",        "java.util.Arrays",        "java.util.Collections",        "java.util.List",        "java.util.Map",        "java.util.Set",    )    /**     * Return `true` if [fullClassName] is visible to scripts.     *     * Called by Rhino's LiveConnect layer when a script tries to access a     * Java class. With `initSafeStandardObjects()`, LiveConnect is disabled     * — so this method is rarely called in practice. It's a safety net.     */    override fun visibleToScripts(fullClassName: String): Boolean {        // Check allowlist first (overrides blocklist)        if (ALLOWED_PREFIXES.any { matchesClass(fullClassName, it) }) {            return true        }        // Check blocklist        if (BLOCKED_PREFIXES.any { matchesClass(fullClassName, it) }) {            Timber.w("SecurityClassShutter blocked: %s", fullClassName)            return false        }        // CRITICAL FIX #47: Default-deny for unknown classes (defense in depth)        Timber.tag(TAG).w("SecurityClassShutter blocking unknown class: %s", fullClassName)        return false    }    /**     * Match [className] against [prefix].     *     * A prefix matches if the class name equals the prefix OR starts with     * `prefix + "."` (so `java.lang.Runtime` matches `java.lang.Runtime`     * but not `java.lang.RuntimePermission`... actually we want to block     * `Runtime` AND `RuntimePermission`, so we use `startsWith(prefix)`).     *     * But we DON'T want `java.lang.String` to match `java.lang.StringBuilder`     * via the allowlist. So we use a stricter match: exact OR     * `prefix + "$"` (nested classes).     */    private fun matchesClass(className: String, prefix: String): Boolean {        if (className == prefix) return true        if (className.startsWith("$prefix.")) return true        // Allow nested classes (e.g., java.util.Map$Entry)        if (className.startsWith("$prefix\$")) return true        return false    }}/** * Extension: convert a [SandboxResult] to a NOUS [Result]. * * Maps each Rhino-specific failure mode to the closest matching * [AppError] variant. This is the public boundary translation — internal * callers (like [SelfModifyEngine]) can pattern-match on [SandboxResult] * directly for finer-grained handling. */private fun SandboxResult.toResult(    correlationId: CorrelationId,    durationNanos: Long,): Result<String> = when (this) {    is SandboxResult.Success -> Result.Success(        data = output,        correlationId = correlationId,        durationNanos = durationNanos,        metadata = mapOf("durationMs" to durationMs.toString()),    )    is SandboxResult.Timeout -> Result.Failure(        error = AppError.Skill.TimedOut(            skillName = "js_sandbox",            durationMs = durationMs,        ),        correlationId = correlationId,        durationNanos = durationNanos,    )    is SandboxResult.MemoryLimit -> Result.Failure(        error = AppError.Skill.Crashed(            skillName = "js_sandbox",            cause = OutOfMemoryError("Sandbox exceeded memory limit (used ${usedMb}MB)"),        ),        correlationId = correlationId,        durationNanos = durationNanos,    )    is SandboxResult.SecurityViolation -> Result.Failure(        error = AppError.Security.IntegrityCheckFailed(            reason = "JS sandbox security violation: $reason",        ),        correlationId = correlationId,        durationNanos = durationNanos,    )    is SandboxResult.ScriptError -> Result.Failure(        error = AppError.Skill.Crashed(            skillName = "js_sandbox",            cause = RuntimeException("JS error at line $line: $message"),        ),        correlationId = correlationId,        durationNanos = durationNanos,    )}